arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "exclude_archived=true&limit=1000&types=public_channel,private_channel" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d.get('error'), d.get('response_metadata',{}).get('messages',''))
    sys.exit(0)
for c in d.get('channels', []):
    if 'incident' in c['name_normalized']:
        print(json.dumps({'id': c['id'], 'name': c['name'], 'topic': c.get('topic',{}).get('value',''), 'is_private': c.get('is_private', False), 'is_archived': c.get('is_archived', False)}))
"

